import { Navigate } from 'react-router-dom';

export default function ProtectedRoute({ children }) {
  // Check if student profile data exists in local storage
  const userInfo = JSON.parse(localStorage.getItem('userInfo'));

  // If no user is logged in, redirect them to the student login page
  if (!userInfo) {
    return <Navigate to="/user/login" replace />;
  }

  // If they are logged in, render the protected component (like UserDashboard)
  return children;
}
